using System;using System.Linq;using System.Collections.Generic;using System.Reflection;using System.Windows.Forms;using BeamScheduleFormatter;
// Native Windows integration: no Excel installation or COM connection is needed.
class AdditionalWorksUiTests {
 static int checks;static void Check(bool ok,string why){checks++;if(!ok)throw new Exception(why);}static void Near(double a,double b,string why){Check(Math.Abs(a-b)<1e-7,why+": "+a+" vs "+b);}
 static T Get<T>(object o,string name){return (T)o.GetType().GetField(name,BindingFlags.Instance|BindingFlags.NonPublic).GetValue(o);}static void Set(object o,string name,object v){o.GetType().GetField(name,BindingFlags.Instance|BindingFlags.NonPublic).SetValue(o,v);}static object Call(object o,string name,params object[] args){return o.GetType().GetMethod(name,BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic).Invoke(o,args);}
 static void Row(ProgramOfWorksForm f,string key,params object[] values){var t=Get<Dictionary<string,ExtraWorkGrid>>(f,"extraGrids")[key];Check(values.Length==t.Inputs,"All input fields provided for "+key);int i=t.Grid.Rows.Add();for(int c=0;c<values.Length;c++)t.Grid.Rows[i].Cells[c].Value=values[c];}
 [STAThread]static void Main(){Application.EnableVisualStyles();AccessCodes.Granted=true;string saved;
  using(var f=new ProgramOfWorksForm()){
   Check(!Get<bool>(f,"initializingWorks"),"Construction finishes before recalculation is enabled");Check(Get<bool>(f,"extraReady"),"Additional sheet dictionaries are complete before first calculation");Set(f,"initializingWorks",true);var sheets=Get<Dictionary<string,ExtraWorkGrid>>(f,"extraGrids");var footingSheet=sheets["WallFooting"];sheets.Remove("WallFooting");try{f.Recalculate();Call(f,"WorksTabChanged");}finally{sheets.Add("WallFooting",footingSheet);Set(f,"initializingWorks",false);}Check(Get<List<string>>(f,"errors").Count==0,"Re-entrant startup calculation waits for incomplete sheet dictionaries");var tabs=Get<TabControl>(f,"tabs");foreach(string section in new[]{"Bill of Quantities","Reinforced Concrete Works","Earthworks","Carpentry and Joinery Works","Pavement Construction","Slope Protection Works"})Check(tabs.TabPages.Cast<TabPage>().Any(t=>t.Text==section),"Startup section present: "+section);var page=tabs.TabPages.Cast<TabPage>().Single(t=>t.Text=="Carpentry and Joinery Works");var inner=page.Controls.OfType<TabControl>().Single();Check(inner.TabCount==7,"Seven complete carpentry tabs");Check(inner.Alignment==TabAlignment.Top&&inner.Multiline,"Full top navigation");var rc=tabs.TabPages.Cast<TabPage>().Single(t=>t.Text=="Reinforced Concrete Works").Controls.OfType<TabControl>().Single();var start=rc.TabPages.Cast<TabPage>().Single(t=>t.Text=="Start");Check(start.Controls.OfType<FlowLayoutPanel>().Single().Controls.OfType<RCSettingsCard>().Count()==3,"RC Start groups settings into three compact cards");Check(Get<NumericUpDown>(f,"leanThickness").Width<=160,"Lean thickness remains a compact numeric field");Check(Get<DataGridView>(f,"boqGrid").CellBorderStyle==DataGridViewCellBorderStyle.Single,"Tables retain visible column dividers");var bill=Get<List<BackupBillItem>>(f,"backupBill");Check(bill.Count==266,"Complete template BOQ before linking");Check(bill.Where(b=>BackupMapping.Unit(b.Unit)=="ls").All(b=>!b.ManualQuantity.HasValue&&!b.WorkbookQuantity.HasValue),"No invented LS quantity");Set(f,"filling",true);
   Row(f,"Carpentry0","BC1","Kitchen",2,0.8,2,0.2);Row(f,"Carpentry1","WC1","Kitchen",2,0.6,1,0);Row(f,"Carpentry2","AC1","Pantry","","",3,0);Row(f,"Carpentry3","R1","Roof",2,2,3,1,12,"Pine");Row(f,"Carpentry4","F1","Floor",1,2,3,1,12,"Pine");Row(f,"Carpentry5","FB1","Eaves",10,2);Row(f,"Carpentry6","TP1","Toilet",2,1.8,1,0.6);
   Row(f,"Trees","T1","Site",350,true);Row(f,"Trees","T2","Retain",350,false);Row(f,"Clearing","C1","Site",10,4,2,"Dimensions","");
   Row(f,"MiscLintelBeam","LB1","Lintel",2,200,300,1,16,2,16,2,10,"Spacing (mm)",150,0,true,0);Row(f,"MiscLintelBeam","LB2","Lintel",2,200,300,1,28,2,28,2,10,"Number of ties",12,0,true,0);
   Row(f,"SlopeRCWall","RW1","Slope",3,1,150,1,1,10,"Spacing (mm)",150,10,"Spacing (mm)",150,0,0,2,0,false);
   Row(f,"WallFooting","WF1","Wall footing",2,.6,300,1,"",true,16,"Number of bars",4,16,"Number of bars",8,1,0,true);
   var ls=bill.First(b=>BackupMapping.Unit(b.Unit)=="ls");ls.ManualQuantity=1;Set(f,"filling",false);Call(f,"Recalculate");Check(Get<List<string>>(f,"errors").Count==0,"Valid additional input has no calculation errors");
   var qs=Get<List<BillQuantity>>(f,"extraSiteQuantities");Near(qs.Single(q=>q.Description=="Modular Base Cabinets").Quantity,3,"Base cabinet measured area");Near(qs.Single(q=>q.Description=="Modular Wall Cabinets").Quantity,1.2,"Wall cabinet separate area");Near(qs.Single(q=>q.PayCode=="1003(4)").Quantity,3,"Aluminum each");Near(qs.Single(q=>q.PayCode=="1003(11)a1").Quantity,20,"Fascia linear metres");Near(qs.Single(q=>q.PayCode=="1003(14)").Quantity,3,"Phenolic net area");Near(qs.Where(q=>q.PayCode=="1003(5)"||q.PayCode=="1003(6)").Sum(q=>q.Quantity),6,"Compatible roof/floor cuts share purchased timber");Near(qs.Single(q=>q.PayCode=="800(3)a2").Quantity,2,"All entered trees included");Near(qs.Single(q=>q.PayCode=="800(1)").Quantity,80,"Clearing area");
   var demands=(List<BackupDemand>)Call(f,"BackupQuantities",false);foreach(var q in qs.Where(q=>q.Section=="Carpentry and Joinery Works")){var d=demands.Single(x=>x.PayCode==q.PayCode&&x.PayDescription==q.PayDescription);Check(d.TargetSlotId!=null&&!d.TargetSlotId.StartsWith("missing:"),"Correct target for "+q.Description);}Check(demands.Where(d=>d.PayCode=="1003(3)").Select(d=>d.TargetSlotId).Distinct().Count()==2,"Duplicate cabinet code has distinct targets");
   var large=demands.Where(d=>d.PayCode=="902(1)a2"&&d.Quantity>0).ToList();Check(large.Count>=2&&large.All(d=>d.PayDescription.Contains("max 42mm")),"All Grade60 sizes route to max42 when 28mm is present");Near(demands.Single(d=>d.PayCode=="510(2)").Quantity,.45,"Slope concrete separate 510 target");Check(demands.Any(d=>d.PayCode=="404(1)a"&&d.Quantity>0),"Slope rebar separate 404 target");Near(demands.Single(d=>d.PayCode=="901(1)").Quantity,.06,"Lean concrete goes to 901 separately");var wall=Get<List<FootingTakeoff>>(f,"wallFootingResults").Single();Near(wall.Backfill,.864,"Wall footing excavation accounts for lean and gravel");
   var ready=Get<Dictionary<string,CheckBox>>(f,"readyMixGroups");var ordinary=(BackupTarget)Call(f,"ConcretePayItem","Structural");ready["Structural"].Checked=true;var rm=(BackupTarget)Call(f,"ConcretePayItem","Structural");Check(BackupMapping.Identity(ordinary)!=BackupMapping.Identity(rm),"Ready-mix setting changes the concrete destination");saved=f.WorksProjectXml();Check(saved.Contains("version=\"21\""),"New schema guards additional sheets");
  }
  using(var f=new ProgramOfWorksForm()){f.OpenProjectXml(saved);var qs=Get<List<BillQuantity>>(f,"extraSiteQuantities");Near(qs.Single(q=>q.Description=="Modular Base Cabinets").Quantity,3,"Cabinets recomputed after reopening");Near(qs.Where(q=>q.PayCode=="1003(5)"||q.PayCode=="1003(6)").Sum(q=>q.Quantity),6,"Stock sharing round trip");Check(Get<List<BackupBillItem>>(f,"backupBill").Any(b=>b.ManualQuantity==1),"Manual LS persists");Check(Get<Dictionary<string,CheckBox>>(f,"readyMixGroups")["Structural"].Checked,"Routing setting persists");}
  Console.WriteLine("PASS: "+checks+" native additional-sheet, BOQ target and save/open integration checks");
 }
}
